  "metodo.hero.h1": { it: "Dove la pietra<br /><em>incontra le mani esperte.</em>", fr: "Là où la pierre<br /><em>rencontre les mains expertes.</em>", en: "Where stone<br /><em>meets expert hands.</em>", de: "Wo der Stein<br /><em>auf erfahrene Hände trifft.</em>" },
  "metodo.step.1.n": { it: "01", fr: "01", en: "01", de: "01" },
  "metodo.step.1.h": { it: "Sopralluogo", fr: "Visite technique", en: "Site visit", de: "Ortsbesichtigung" },
  "metodo.step.1.p": { it: "Visita gratuita per analizzare il contesto, valutare la fattibilità tecnica e ascoltare l'esigenza del progettista o del committente.", fr: "Visite gratuite pour analyser le contexte, évaluer la faisabilité technique et écouter les besoins du concepteur ou du maître d'ouvrage.", en: "Free visit to analyse the context, assess technical feasibility and listen to the needs of the designer or the client.", de: "Kostenloser Besuch, um den Kontext zu analysieren, die technische Machbarkeit zu beurteilen und die Anforderungen des Planers oder Bauherrn zu erfassen." },
  "metodo.step.2.n": { it: "02", fr: "02", en: "02", de: "02" },
  "metodo.step.2.h": { it: "Preventivo", fr: "Devis", en: "Quote", de: "Kostenvoranschlag" },
  "metodo.step.2.p": { it: "Quotazione dettagliata con selezione del materiale, finitura, schema di posa e tempistiche. Trasporto incluso nel prezzo finale.", fr: "Devis détaillé avec sélection du matériau, finition, schéma de pose et délais. Transport inclus dans le prix final.", en: "Detailed quote with material selection, finish, laying pattern and timeline. Transport included in the final price.", de: "Detaillierter Kostenvoranschlag mit Materialauswahl, Oberfläche, Verlegemuster und Zeitplan. Transport im Endpreis inbegriffen." },
  "metodo.step.3.n": { it: "03", fr: "03", en: "03", de: "03" },
  "metodo.step.3.h": { it: "Fornitura", fr: "Fourniture", en: "Supply", de: "Lieferung" },
  "metodo.step.3.p": { it: "Selezione accurata in cava dei blocchi e del materiale di lavoro, taglio su misura e consegna in cantiere.", fr: "Sélection rigoureuse en carrière des blocs et du matériau de travail, découpe sur mesure et livraison sur le chantier.", en: "Careful selection of blocks and working material at the quarry, made-to-measure cutting and delivery to the site.", de: "Sorgfältige Auswahl der Blöcke und des Arbeitsmaterials im Steinbruch, maßgenauer Zuschnitt und Lieferung auf die Baustelle." },
  "metodo.step.4.n": { it: "04", fr: "04", en: "04", de: "04" },
  "metodo.step.4.h": { it: "Posa", fr: "Pose", en: "Laying", de: "Verlegung" },
  "metodo.step.4.p": { it: "Squadra interna di posatori specializzati. Cantiere pulito, consegna nei tempi concordati, garanzia sul lavoro eseguito.", fr: "Équipe interne de poseurs spécialisés. Chantier propre, livraison dans les délais convenus, garantie sur le travail réalisé.", en: "In-house team of specialised installers. Clean site, delivery within the agreed timeframe, warranty on the work carried out.", de: "Internes Team spezialisierter Verleger. Saubere Baustelle, Lieferung in der vereinbarten Zeit, Garantie auf die ausgeführte Arbeit." },
  "metodo.cta.h": { it: "Partiamo dal <em>sopralluogo.</em>", fr: "Commençons par la <em>visite technique.</em>", en: "Let's start with the <em>site visit.</em>", de: "Beginnen wir mit der <em>Ortsbesichtigung.</em>" },
  "metodo.cta.sub": { it: "Prenota una visita gratuita: ti ricontattiamo entro 48 ore lavorative.", fr: "Réservez une visite gratuite : nous vous recontactons sous 48 heures ouvrées.", en: "Book a free visit: we will get back to you within 48 working hours.", de: "Buchen Sie einen kostenlosen Besuch: Wir melden uns innerhalb von 48 Arbeitsstunden." },
