  "lavori.cta.h": { it: "Un progetto simile <em>in mente?</em>", fr: "Un projet similaire <em>en tête ?</em>", en: "A similar project <em>in mind?</em>", de: "Ein ähnliches Projekt <em>im Sinn?</em>" },
  "lavori.cta.sub": { it: "Raccontaci cosa hai in mente: ti ricontattiamo entro 48 ore lavorative.", fr: "Parlez-nous de ce que vous avez en tête : nous vous recontactons sous 48 heures ouvrées.", en: "Tell us what you have in mind: we will get back to you within 48 working hours.", de: "Erzählen Sie uns, was Sie im Sinn haben: Wir melden uns innerhalb von 48 Arbeitsstunden." },
  // ---- CHISIAMO (#8 i18n) ----
  "chisiamo.crumb.home": { it: "Home", fr: "Accueil", en: "Home", de: "Startseite" },
  "chisiamo.hero.h1": { it: "Una tradizione di famiglia,<br /><em>una nuova generazione.</em>", fr: "Une tradition familiale,<br /><em>une nouvelle génération.</em>", en: "A family tradition,<br /><em>a new generation.</em>", de: "Eine Familientradition,<br /><em>eine neue Generation.</em>" },
  "chisiamo.hero.lead": { it: "Quarant'anni di Pietra di Luserna lavorata e posata a mano, tra Italia, Francia e Svizzera.", fr: "Quarante ans de Pierre de Luserne taillée et posée à la main, entre l'Italie, la France et la Suisse.", en: "Forty years of Luserna Stone crafted and laid by hand, between Italy, France and Switzerland.", de: "Vierzig Jahre von Hand bearbeiteter und verlegter Luserna-Stein, zwischen Italien, Frankreich und der Schweiz." },
  "chisiamo.storia.eyebrow": { it: "La nostra storia", fr: "Notre histoire", en: "Our story", de: "Unsere Geschichte" },
  "chisiamo.storia.h2": { it: "Dalle mani di Mauro,<br />alla guida di Massimo.", fr: "Des mains de Mauro,<br />à la direction de Massimo.", en: "From Mauro's hands,<br />to Massimo's leadership.", de: "Von Mauros Händen,<br />zu Massimos Führung." },
  "chisiamo.storia.p1": { it: "Nikestone nasce dalle mani di <strong>Mauro Angelino</strong>, che a fine carriera ha lasciato il compito di guidare l'attività al figlio <strong>Massimo Angelino</strong>: quattro decenni di pietra lavorata e posata in cantieri tra Francia, Germania, Svizzera e Italia.", fr: "Nikestone est née des mains de <strong>Mauro Angelino</strong>, qui, en fin de carrière, a confié la direction de l'activité à son fils <strong>Massimo Angelino</strong> : quatre décennies de pierre taillée et posée sur des chantiers entre la France, l'Allemagne, la Suisse et l'Italie.", en: "Nikestone was born from the hands of <strong>Mauro Angelino</strong>, who at the end of his career passed on the leadership of the business to his son <strong>Massimo Angelino</strong>: four decades of stone crafted and laid on sites across France, Germany, Switzerland and Italy.", de: "Nikestone entstand aus den Händen von <strong>Mauro Angelino</strong>, der am Ende seiner Laufbahn die Leitung des Betriebs an seinen Sohn <strong>Massimo Angelino</strong> übergab: vier Jahrzehnte bearbeiteter und verlegter Stein auf Baustellen zwischen Frankreich, Deutschland, der Schweiz und Italien." },
  "chisiamo.storia.p2": { it: "Lavoriamo per architetti, interior designer, general contractor e committenti privati che vogliono superfici autentiche e risultati garantiti. Ogni progetto è unico, un dialogo costante tra committente e azienda.", fr: "Nous travaillons pour des architectes, des architectes d'intérieur, des general contractors et des maîtres d'ouvrage privés qui recherchent des surfaces authentiques et des résultats garantis. Chaque projet est unique, un dialogue constant entre le maître d'ouvrage et l'entreprise.", en: "We work for architects, interior designers, general contractors and private clients who want authentic surfaces and guaranteed results. Every project is unique, a constant dialogue between client and company.", de: "Wir arbeiten für Architekten, Innenarchitekten, Generalunternehmer und private Bauherren, die authentische Oberflächen und garantierte Ergebnisse wünschen. Jedes Projekt ist einzigartig, ein ständiger Dialog zwischen Bauherr und Unternehmen." },
  "chisiamo.storia.sign": { it: "Massimo & Mauro Angelino", fr: "Massimo & Mauro Angelino", en: "Massimo & Mauro Angelino", de: "Massimo & Mauro Angelino" },
  "chisiamo.storia.cta": { it: "Vedi i nostri lavori", fr: "Voir nos réalisations", en: "See our work", de: "Unsere Arbeiten ansehen" },
  "chisiamo.cta.h": { it: "Costruiamo qualcosa <em>che resta.</em>", fr: "Construisons quelque chose <em>qui dure.</em>", en: "Let's build something <em>that lasts.</em>", de: "Lassen Sie uns etwas bauen, <em>das bleibt.</em>" },
