  "cataloghi.card.1.h": { it: "RIVESTIMENTI MURI E TETTI", fr: "REVÊTEMENTS MURS ET TOITURES", en: "WALL AND ROOF CLADDING", de: "WAND- UND DACHVERKLEIDUNGEN" },
  "cataloghi.card.1.desc": { it: "Rivestimenti in Pietra di Luserna per ville di lusso. Muri interni ed esterni, camini, scale, bagni di pregio.", fr: "Revêtements en Pierre de Luserne pour villas de prestige. Murs intérieurs et extérieurs, cheminées, escaliers, salles de bains de standing.", en: "Luserna Stone cladding for luxury villas. Interior and exterior walls, fireplaces, staircases, fine bathrooms.", de: "Verkleidungen aus Luserna-Stein für Luxusvillen. Innen- und Außenwände, Kamine, Treppen, hochwertige Bäder." },
  "cataloghi.card.1.cta": { it: "Richiedi PDF", fr: "Demander le PDF", en: "Request PDF", de: "PDF anfordern" },
